              <label [for]="'pool-member-share-' + id">Share %</label>
              <input [id]="'pool-member-share-' + id" data-testid="pool-member-share" formControlName="share" inputmode="decimal" />
              <label [for]="'pool-member-from-' + id">From (optional)</label>
