import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';
test("tmp asof", async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg, "2026-03-01");
    const a = ui.must(await ui.addPerson(pg, {"name": "Ada", "grade": "A"}));
    const b = ui.must(await ui.addPerson(pg, {"name": "Ben", "grade": "B"}));
    expect(await ui.addPeriod(pg, {"name": "P1", "from": "2026-03-01", "to": "2026-03-10"})).toBe(true);
    expect(await ui.addPeriod(pg, {"name": "P2", "from": "2026-03-11", "to": "2026-03-20"})).toBe(true);
    await ui.setSetting(pg, "pot", "10.00");
    expect(await ui.addPool(pg, "P")).toBe(true);
    expect(await ui.addPoolMember(pg, "P", {"member": "Ada", "share": "50.00"})).toBe(true);
    expect(await ui.addPoolMember(pg, "P", {"member": "Ben", "share": "50.00"})).toBe(true);
    await ui.setToday(pg, "2026-03-11");
    await ui.setSetting(pg, "pot", "20.00");
    expect(await ui.hold(pg, b, {"from": "2026-03-11"})).toBe(true);
    await ui.setToday(pg, "2026-03-21");
    await ui.setSetting(pg, "pot", "30.00");
    await ui.setAsOf(pg, "2026-03-15");
    await expect(pg.getByTestId("pool-member-P-" + a).getByTestId("pool-cut")).toHaveText("20.00");
    await expect(pg.getByTestId("pool-member-P-" + a).getByTestId("pool-cut-P1")).toHaveText("5.00");
    await expect(pg.getByTestId("pool-member-P-" + a).getByTestId("pool-cut-P2")).toHaveCount(0);
    await ui.clearAsOf(pg);
    await ui.refresh(pg);
    await expect(pg.getByTestId("pool-member-P-" + a).getByTestId("pool-cut")).toHaveText("30.00");
    await expect(pg.getByTestId("pool-member-P-" + a).getByTestId("pool-cut-P2")).toHaveText("20.00");
    await expect(pg.getByTestId("pool-member-P-" + b).getByTestId("pool-cut-P1")).toHaveText("5.00");
});
EOF
